1	// Shared VPS order core — used by the wallet flow (lib/actions.ts orderServer),
2	// the direct-pay flow (payAndDeploy), and the Stripe confirm route so a paid
3	// checkout can provision immediately. Plain server module (not "use server").
4	import { z } from "zod";
5	import type { User } from "@prisma/client";
6	import { db } from "./db";
7	import { debitWallet, InsufficientBalanceError } from "./wallet";
8	import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
9	import { annualDiscountPct } from "./annual-discount";
10	import { dedicatedIpMonthlyCents } from "./dedicated-ip";
11	import { capacityCheck, diskCapacityCheck } from "./capacity";
12	import { invoiceCreateData } from "./invoices";
13	import { maybeRewardReferral } from "./actions-growth";
14	import { currentPromo } from "./promotions";
15	import {
16	  claimFirstMonthFree,
17	  confirmReservation,
18	  firstMonthFreeEnabled,
19	  firstMonthFreeAppliesTo,
20	  setPromoOrderRef,
21	} from "./promo-redemption";
22	import { extraDiskPerGbCents } from "./disk-expand";
23	import {
24	  EXTRA_DISK_MAX_ADD_GB,
25	  EXTRA_DISK_MAX_TOTAL_GB,
26	  effectiveDiskGB,
27	  extraDiskCentsAt,
28	  extraDiskLabel,
