88	/**
89	 * The price an order was SOLD at: the total, and the promo rate that produced it.
90	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
91	 *
92	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
93	 * path quoted a total, charged the CARD its share of that total at Stripe, and
94	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
95	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
96	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
97	 * so a rotation between "customer clicked Deploy" and "customer came back from
98	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
99	 * out of the wallet with no new consent. With no balance to take it from, the
100	 * payment was captured and no server was created.
101	 *
102	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
103	 * Stripe metadata for exactly this reason; the order path was the one that
104	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
105	 * the customer was shown is not recomputed later, it is carried.
106	 *
107	 * `promoPercent` and `promoName` travel WITH the total because they are not
108	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
109	 * at (every later proration prices against it), and the promo name is the ledger
110	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
111	 * today's 15% would hand every later proration the wrong basis and print a
112	 * discount on the invoice that does not match the money taken.
113	 */
114	export type OrderPrice = {
115	  /** Total to charge, in cents — the figure the customer consented to. */
116	  chargeCents: number;
117	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
118	  promoPercent: number;
119	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
120	  promoName: string;
121	};
122	
123	/** The sold price implied by a quote — the ONE place a quote becomes a price. */
124	export function orderPriceOf(quote: {
125	  chargeCents: number;
126	  promo: { discountPercent: number; name: string };
127	}): OrderPrice {
128	  return {
129	    chargeCents: quote.chargeCents,
130	    promoPercent: quote.promo.discountPercent,
131	    promoName: quote.promo.name,
132	  };
133	}
