359	/**
360	 * Place an order: validate, charge the wallet (unless a free admin grant),
361	 * create the Server + PROVISION job. Returns the new server id. Does NOT
362	 * redirect. Callers must ensure funds exist (or pass free) — this still
363	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
364	 *
365	 * `sold` overrides the recomputed price with the one the order was actually SOLD
366	 * at — the card-paid path passes the figure stamped on the Checkout session
367	 * BEFORE the card was charged, so the confirm redirect settles the price the
368	 * customer consented to instead of re-pricing against whatever promo is running
369	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
370	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
371	 * quote, which it computed moments ago in the same request. See OrderPrice.
372	 */
373	/**
374	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
375	 * any failure so nothing partial survives. Kept separate from the order tx so a
376	 * wallet order can surface the failure before any money moves, and a card order
377	 * (already paid) can swallow it without stranding the paid provision.
378	 *
379	 * Guards, all enforced here: first-time-only (no prior paid server), the
380	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
381	 * (the two @@unique constraints on CouponRedemption).
382	 */
383	async function claimOrderCoupon(opts: {
384	  couponId: string;
385	  maxRedemptions: number | null;
386	  firstTimeOnly: boolean;
387	  userId: string;
388	  ipHash: string | null;
389	  amountCents: number;
390	}): Promise<void> {
391	  await db.$transaction(async (tx) => {
392	    if (opts.firstTimeOnly) {
393	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
394	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
395	    }
396	    // Atomic conditional increment — the only thing between the last free slot and
397	    // an over-redemption when two orders race for it.
398	    const claim = await tx.coupon.updateMany({
399	      where:
400	        opts.maxRedemptions === null
401	          ? { id: opts.couponId, active: true }
402	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
403	      data: { timesRedeemed: { increment: 1 } },
404	    });
405	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
406	    try {
407	      await tx.couponRedemption.create({
408	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
409	      });
410	    } catch {
411	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
412	      // this person. Throwing rolls back the increment above with it.
413	      throw new OrderError("You’ve already used this code.");
414	    }
415	  });
416	}
417	
418	/**
419	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
420	 *
421	 * The card leg discounts `cardCents` up front and only settles the redemption
422	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
423	 * paid provision is never stranded. Without this pre-check, a customer who has
424	 * already used a one-per-person code (or isn't first-time) still gets the
425	 * discounted card charge and the swallow hides it. So before we send them to
426	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
427	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
428	 * (a race could still lose the atomic claim at settle time — that path stays
429	 * swallowed by design), but it closes the everyday bypass.
430	 */
431	export async function orderCouponClaimable(opts: {
432	  couponId: string;
433	  firstTimeOnly: boolean;
434	  maxRedemptions: number | null;
435	  userId: string;
436	  ipHash: string | null;
437	}): Promise<{ ok: true } | { ok: false; error: string }> {
438	  if (opts.firstTimeOnly) {
439	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
440	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
441	  }
442	  const byUser = await db.couponRedemption.findUnique({
443	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
444	  });
445	  if (byUser) return { ok: false, error: "You’ve already used this code." };
446	  if (opts.ipHash) {
447	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
448	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
449	  }
450	  if (opts.maxRedemptions !== null) {
451	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
452	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
453	  }
454	  return { ok: true };
455	}
