457	export async function placeOrder(
458	  user: User,
459	  intent: OrderIntent,
460	  sold?: OrderPrice | null,
461	  opts?: { ipHash?: string | null; campaign?: string; promoReservationToken?: string | null },
462	): Promise<string> {
463	  const quote = await orderQuote(intent);
464	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
465	  // Everything below bills off THESE three, never off `quote.chargeCents` /
466	  // `promo` directly: when a sold price is present it is the whole truth about
467	  // what this order costs and what rate it was sold at.
468	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
469	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
470	  const promoName = sold?.promoName || promo.name;
471	  // Note the intro discount on the billing document (first term only; renews full).
472	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
473	
474	  // Managed first-month-free — how this order settles the credit depends on the path:
475	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
476	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
477	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
478	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
479	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
480	  //     the double-claim race. No token => this order was sold at FULL price, so there
481	  //     is nothing to grant. We deliberately do NOT infer the credit from
482	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
483	  //     order), which would record a redemption for a purchase that never got one.
484	  const walletPromoApplied = !sold && promoCreditCents > 0;
485	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
486	
487	  const cap = await capacityCheck(plan.id);
488	  if (!cap.ok) throw new OrderError(cap.reason);
489	
490	  let nodeId: string | null = null;
491	  if (intent.nodeId) {
492	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
493	    if (!n) throw new OrderError("Selected location is not available.");
494	    nodeId = n.id;
495	  } else {
496	    const n = await scheduleNode(plan.ramMB);
497	    nodeId = n?.id ?? null;
498	  }
499	
500	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
501	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
502	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
503	
504	  const addons = {
505	    malwareScanner: !!intent.addonMalware,
506	    dailyBackup: !!intent.addonBackup,
507	    docker: !!intent.addonDocker,
508	  };
509	  const isAdmin = user.role === "ADMIN";
510	  const freeRequested = !!intent.free && isAdmin;
511	  if (!freeRequested && user.balanceCents < chargeCents) throw new OrderError("Insufficient balance.");
512	
513	  // Claim the coupon BEFORE the order tx, so a wallet order fails cleanly (no
514	  // money moved) if the last slot just went. A free admin grant never consumes a
515	  // customer coupon. On the card-settle path the payment already cleared, so a
516	  // late claim failure must not strand the paid provision — log and continue.
517	  if (!freeRequested && quote.couponId && quote.couponDiscountCents > 0) {
518	    try {
519	      await claimOrderCoupon({
520	        couponId: quote.couponId,
521	        maxRedemptions: quote.couponMaxRedemptions,
522	        firstTimeOnly: quote.couponFirstTimeOnly,
523	        userId: user.id,
524	        ipHash: opts?.ipHash ?? null,
525	        amountCents: quote.couponDiscountCents,
526	      });
527	    } catch (e) {
528	      if (!sold) throw e; // wallet path: nothing charged yet — surface it
529	      console.error(`[order] coupon claim failed on a paid order for ${user.id}`, e);
530	    }
531	  }
532	
533	  const newKey = (intent.sshPublicKey ?? "").trim();
534	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
535	
536	  let server;
537	  try {
538	    server = await db.$transaction(async (tx) => {
539	      // ATOMIC first-month-free claim, INSIDE the charge tx (mirrors claimOrderCoupon).
540	      // Contend for the redemption BEFORE debiting so the debit amount matches the
541	      // outcome. A lost claim never throws — on the wallet path we add the credit
542	      // back and charge FULL; on the card path the money already settled at the sold
543	      // price (screened by the pre-checkout guard in actions.ts), so we keep it and
544	      // record nothing — the same swallow discipline the coupon path uses.
545	      let debitCents = chargeCents;
546	      let promoNoteFinal = promoNote;
547	      let promoClaimId: string | null = null;
548	      let soldFull = false; // wallet order that lost the claim and paid full price
549	      if (!freeRequested && cardPromoToken) {
550	        // CARD/Stripe path: confirm the hold reserved before the card was charged.
551	        // The card already settled at the sold (discounted) price; confirming just
552	        // flips the hold to CONSUMED and anchors it. NEVER a second debit here.
553	        const confirmed = await confirmReservation(tx, cardPromoToken);
554	        if (confirmed) {
555	          promoClaimId = confirmed.id;
556	        } else {
557	          // The hold is gone (released/swept) but the card already paid the discounted
558	          // leg. This is unreachable while the hold outlives the payable session, but
559	          // if it ever happens we must NOT charge more than the customer was shown.
560	          // Try to record the grant so a later renewal can convert it; if even that
561	          // loses (the slot is now another order's), keep the discounted charge and
562	          // log — the same swallow discipline the paid-coupon path uses.
563	          const fallback = await claimFirstMonthFree(tx, {
564	            userId: user.id,
565	            ipHash: opts?.ipHash ?? null,
566	            serviceType: "VPS",
567	            campaign: opts?.campaign ?? "",
568	            chargedCents: chargeCents,
569	          });
570	          if (fallback.claimed) promoClaimId = fallback.id;
571	          else console.error(`[order] first-month-free hold ${cardPromoToken} vanished before confirm for ${user.id}; kept sold price`);
572	        }
573	      } else if (!freeRequested && walletPromoApplied) {
574	        // WALLET path: atomic INSERT inside the charge tx. A lost claim means this
575	        // account/IP already redeemed — add the credit back and charge FULL price.
576	        const claim = await claimFirstMonthFree(tx, {
577	          userId: user.id,
578	          ipHash: opts?.ipHash ?? null,
579	          serviceType: "VPS",
580	          campaign: opts?.campaign ?? "",
581	          chargedCents: chargeCents,
582	        });
583	        if (claim.claimed) {
584	          promoClaimId = claim.id;
585	        } else {
586	          debitCents = chargeCents + promoCreditCents; // full price
587	          promoNoteFinal = "";
588	          soldFull = true;
589	        }
590	      }
591	      // The rate this term was actually sold at: 0% off when a wallet order lost the
592	      // claim and paid full, otherwise the promo/sold percent (100 admin grant).
593	      const effectivePromoPercent = freeRequested ? 100 : soldFull ? 0 : promoPercent;
594	      if (!freeRequested) {
595	        // For a multi-month term (Annual etc.), spell out the effective monthly-
596	        // equivalent of the PLAN portion on the billing document, derived from the
597	        // very `regularPlanCents` that was charged (its term discount already baked
598	        // in) — never a second computation. So an annual line reads "Annual
599	        // ($8.09/mo)" and the customer can see the yearly commitment AND its real
600	        // per-month rate. Omitted for the 1-month term, where it would just repeat
601	        // the monthly price.
602	        const effMonthlyCents = term.months > 1 ? Math.round(quote.regularPlanCents / term.months) : 0;
603	        const termLabel =
604	          term.months > 1 ? `${term.label} ($${(effMonthlyCents / 100).toFixed(2)}/mo)` : term.label;
605	        await debitWallet(tx, user.id, debitCents);
606	        await tx.walletTransaction.create({
607	          data: {
608	            userId: user.id,
609	            amountCents: -debitCents,
610	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`,
611	          },
612	        });
613	        // Billing document for the charge — created inside the same debit tx so it
614	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
615	        // Extra disk gets its OWN line so the customer can see exactly what the
616	        // permanent storage costs; the lines always sum back to debitCents.
617	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`;
618	        // Both add-ons get their OWN line; the base plan line is the remainder, so
619	        // the lines always sum back to debitCents.
620	        const planLineCents = debitCents - extraDiskCents - backupCents;
621	        await tx.invoice.create({
622	          data: invoiceCreateData({
623	            userId: user.id,
624	            description: lineDesc,
625	            status: "PAID",
626	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
627	            lineItems: [
628	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
629	              ...(extraDiskCents > 0
630	                ? [
631	                    {
632	                      description:
633	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
634	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
635	                      qty: 1,
636	                      unitCents: extraDiskCents,
637	                      amountCents: extraDiskCents,
638	                    },
639	                  ]
640	                : []),
641	              ...(backupCents > 0
642	                ? [
643	                    {
644	                      description:
645	                        `${backupTierSpec(backupTier).label} backups (keep ${backupTierSpec(backupTier).keep}) — ${term.label} ` +
646	                        `($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
647	                      qty: 1,
648	                      unitCents: backupCents,
649	                      amountCents: backupCents,
650	                    },
651	                  ]
652	                : []),
653	            ],
654	          }),
655	        });
656	      }
657	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
658	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
659	        if (!exists) await tx.sshKey.create({ data: { userId: user.id, name: keyName, publicKey: newKey } });
660	      }
661	      const s = await tx.server.create({
662	        data: {
663	          name: intent.hostname,
664	          hostname: intent.hostname,
665	          userId: user.id,
666	          planId: plan.id,
667	          osTemplateId: os.id,
668	          nodeId,
669	          addons,
670	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
671	          // storage for easy restore") and re-confirms it on the Review step, but
672	          // `addons.dailyBackup` was write-only: the worker declares the key and
673	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
674	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
675	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
676	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
677	          // job was ever enqueued. A customer would discover the safety net they
678	          // were promised did not exist at the moment they needed it. Bridge it
679	          // here, at the point of sale. A PAID backup tier (PLUS) implies backups
680	          // are on regardless of the free "Daily auto-backups" toggle — you cannot
681	          // sell retention on a schedule that never runs. `backupTier`/`backupKeep`
682	          // are the columns the retention lever (worker/index.ts backupCreate)
683	          // reads; keep null on FREE so it falls back to the tier default.
684	          autoBackup: !!intent.addonBackup || backupTier !== "FREE",
685	          backupIntervalHours:
686	            !!intent.addonBackup || backupTier !== "FREE" ? backupTierSpec(backupTier).intervalHours : null,
687	          backupTier,
688	          backupKeep: backupTier === "FREE" ? null : backupTierSpec(backupTier).keep,
689	          termMonths: term.months,
690	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
691	          // later proration prices the plan delta against this number instead of
692	          // whatever promo happens to be running when the customer clicks resize
693	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
694	          // half of a round trip by choosing the date, and pockets the spread.
695	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
696	          // this scalar and the cash collected describe the same transaction.
697	          // A free admin grant recorded as 100: nothing was paid for these months,
698	          // so nothing may ever prorate out of them.
699	          //
700	          // `effectivePromoPercent` — not `promo.discountPercent` — because a
701	          // card-paid order settles the rate it was SOLD at (see OrderPrice), which
702	          // may no longer be the promo running now, AND because a wallet order that
703	          // lost the first-month-free claim paid FULL price (0% off): recording 100
704	          // there would let a later downgrade prorate out a discount nobody was
705	          // charged. Recording today's rate against a price collected under a
706	          // different one is exactly the drift this column exists to prevent.
707	          termPromoPercent: effectivePromoPercent,
708	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
709	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
710	          // born at its full size, with no separate expansion job.
711	          extraDiskGB,
712	          wantsDedicatedIp: !!intent.dedicatedIp,
713	          isFree: freeRequested,
714	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
715	        },
716	      });
717	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
718	      // Anchor the redemption to the created server so the renewal worker can flip
719	      // `renewed` when this customer bills their second term, and stamp the true
720	      // first-term charge. Same tx, so it commits (or rolls back) with the order.
721	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
722	      return s;
723	    });
724	  } catch (e) {
725	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
726	    throw e;
727	  }
728	
729	  await db.auditLog.create({
730	    data: {
731	      userId: user.id,
732	      action: "server.order",
733	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
734	    },
735	  });
736	  if (!freeRequested) {
737	    try {
738	      await maybeRewardReferral(user.id);
739	    } catch {
740	      /* non-fatal */
741	    }
742	  }
743	  return server.id;
744	}
