239	/**
240	 * A cents amount that arrived from OUTSIDE this process (Stripe metadata) and is
241	 * about to be handed to `debitWallet`. Integer, non-negative, finite — anything
242	 * else is refused rather than coerced, for the same reason `parseOrderPrice`
243	 * refuses a half-valid price: the caller's `?? quote.prorateCents` fallback would
244	 * silently RE-PRICE the purchase at confirm time, which is the H2 incident.
245	 */
246	function parseChargeCents(raw: unknown): number | null {
247	  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
248	  return raw;
249	}
250	
251	function parseId(raw: unknown): string | null {
252	  return typeof raw === "string" && raw.length > 0 ? raw : null;
253	}
