255	/**
256	 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
257	 *
258	 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
259	 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
260	 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
261	 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
262	 * not read this session" into "this session has no purchase metadata", and
263	 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
264	 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
265	 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
266	 * class of invisible failure that file was written to end, one layer up.
267	 *
268	 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
269	 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
270	 * returning a lie) and classified by a pure function over its metadata.
271	 */
272	export type CheckoutPurpose =
273	  | {
274	      kind: "order";
275	      userId: string;
276	      intent: OrderIntent;
277	      sold: OrderPrice | null;
278	      campaign: string;
279	      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
280	      promoReservationToken: string | null;
281	    }
282	  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
283	  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
284	  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
285	  | { kind: "topup"; userId: string | null }
286	  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
287	  | { kind: "unpaid" }
288	  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
289	  | { kind: "unreadable"; userId: string | null; detail: string };
290	
291	/**
292	 * Classify a retrieved session. Pure — no clock, no network, no database — so the
293	 * routing decision is unit-testable and identical for the redirect and the webhook.
294	 */
295	export function classifyCheckoutSession(
296	  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
297	): CheckoutPurpose {
298	  const md = session.metadata ?? null;
299	  const userId = parseId(md?.nxeonUserId);
300	  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };
301	
302	  const orderRaw = md?.nxeonOrder;
303	  if (orderRaw) {
304	    let intent: unknown;
305	    try {
306	      intent = JSON.parse(orderRaw);
307	    } catch {
308	      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
309	    }
310	    if (!intent || typeof intent !== "object") {
311	      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
312	    }
313	    return {
314	      kind: "order",
315	      userId,
316	      intent: intent as OrderIntent,
317	      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
318	      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
319	      promoReservationToken: parseId(md?.nxeonPromoReservation),
320	    };
321	  }
322	
323	  const resizeRaw = md?.nxeonResize;
324	  if (resizeRaw) {
325	    let p: Record<string, unknown>;
326	    try {
327	      p = JSON.parse(resizeRaw) as Record<string, unknown>;
328	    } catch {
329	      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
330	    }
331	    const serverId = parseId(p?.serverId);
332	    const planId = parseId(p?.planId);
333	    const chargeCents = parseChargeCents(p?.chargeCents);
334	    if (!serverId || !planId || chargeCents === null) {
335	      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
336	    }
337	    return { kind: "resize", userId, serverId, planId, chargeCents };
338	  }
339	
340	  const expandRaw = md?.nxeonDiskExpand;
341	  if (expandRaw) {
342	    let p: Record<string, unknown>;
343	    try {
344	      p = JSON.parse(expandRaw) as Record<string, unknown>;
345	    } catch {
346	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is not valid JSON" };
347	    }
348	    const serverId = parseId(p?.serverId);
349	    const addGB = parseChargeCents(p?.addGB);
350	    const chargeCents = parseChargeCents(p?.chargeCents);
351	    if (!serverId || addGB === null || chargeCents === null) {
352	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is missing serverId/addGB/chargeCents" };
353	    }
354	    return { kind: "diskExpand", userId, serverId, addGB, chargeCents };
355	  }
356	
357	  return { kind: "topup", userId };
358	}
