360	/**
361	 * Retrieve a Checkout session ONCE. Throws when Stripe cannot be read — the caller
362	 * must never be able to mistake a transport failure for "this session is a top-up".
363	 */
364	export async function retrieveCheckoutSession(sessionId: string): Promise<Stripe.Checkout.Session> {
365	  if (!stripeConfigured()) throw new Error("Stripe is not configured");
366	  return stripe().checkout.sessions.retrieve(sessionId);
367	}
368	
369	/** Retrieve + classify in one step. Throws on a Stripe read failure, never lies. */
370	export async function getCheckoutPurpose(sessionId: string): Promise<CheckoutPurpose> {
371	  return classifyCheckoutSession(await retrieveCheckoutSession(sessionId));
372	}
