374	/**
375	 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
376	 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
377	 * bought for its own sake.
378	 *
379	 * The wallet is the settlement bus for every card-paid purchase: the card amount
380	 * is credited in, then the purchase debits the full total back out. That credit is
381	 * plumbing, not a product, and it must not be documented as one.
382	 *
383	 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
384	 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
385	 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
386	 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
387	 * against their card statement saw twice their spend. Each document was internally
388	 * consistent; there were simply two of them for one payment. worker/billing.ts
389	 * already states the rule for the renewal path: "No invoice for the card leg …
390	 * a second document for the card portion would double-count the same revenue."
391	 *
392	 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
393	 * "did this session fund a purchase" has one answer, not two.
394	 */
395	export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
396	  return !!(metadata?.nxeonOrder || metadata?.nxeonResize || metadata?.nxeonDiskExpand);
397	}
