399	/**
400	 * Credit a user's wallet for a completed Checkout session, idempotently.
401	 * Called from both the success-redirect confirm route (works without HTTPS)
402	 * and the webhook (belt-and-suspenders once HTTPS is available).
403	 * Returns true if a credit was applied this call.
404	 *
405	 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
406	 * fetches it once and both the credit and the fulfilment routing read that single
407	 * object, so the two can never disagree about what this payment was (and a Stripe
408	 * read failure surfaces in one place, loudly, instead of four times as `null`).
409	 */
410	export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
411	  const userId = session.metadata?.nxeonUserId;
412	  const cents = session.amount_total ?? 0;
413	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
414	
415	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
416	  // session id inside the description.
417	  const legacy = await db.walletTransaction.findFirst({
418	    where: { stripeSessionId: null, description: { contains: session.id } },
419	  });
420	  if (legacy) return false;
421	
422	  // Is this credit a product the customer bought, or the funding leg of something
423	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
424	  // a billing document — see isPurchaseLegSession for the incident.
425	  const purchaseLeg = isPurchaseLegSession(session.metadata);
426	
427	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
428	  // read-then-write check. The confirm-redirect and the webhook can arrive
429	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
430	  // only the database can safely decide the winner. P2002 == already credited.
431	  const ops: Prisma.PrismaPromise<unknown>[] = [
432	    db.walletTransaction.create({
433	      data: {
434	        userId,
435	        amountCents: cents,
436	        description: `Stripe payment (${session.id})`,
437	        stripeSessionId: session.id,
438	      },
439	    }),
440	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
441	    db.notification.create({
442	      data: {
443	        userId,
444	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
445	        href: "/dashboard/billing",
446	      },
447	    }),
448	  ];
449	  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
450	  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
451	  let invoiceOpIndex = -1;
452	  if (!purchaseLeg) {
453	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
454	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
455	    // the credit idempotent also prevents a duplicate invoice on replay.
456	    //
457	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
458	    // disk-expansion it funds issues the one invoice for the whole purchase, and
459	    // that document — not this one — is what the customer's card statement shows.
460	    // If the fulfilment then fails the money stays in the wallet as an ordinary
461	    // credit (ledger row + notification), and the invoice is issued by whatever it
462	    // is eventually spent on; inventing a top-up document at that point would
463	    // double-count the same dollars all over again the moment they deploy.
464	    // Remember WHERE in the batch this lands, so the created row's id can be read
465	    // back out of the transaction result. The receipt email promises the customer
466	    // an attached invoice, and it can only keep that promise if it knows the id.
467	    invoiceOpIndex = ops.length;
468	    ops.push(
469	      db.invoice.create({
470	        data: invoiceCreateData({
471	          userId,
472	          description: "Wallet top-up",
473	          status: "PAID",
474	          lineItems: [
475	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
476	          ],
477	        }),
478	      }),
479	    );
480	  }
481	  let invoiceId: string | undefined;
482	  try {
483	    const results = await db.$transaction(ops);
484	    if (invoiceOpIndex >= 0) {
485	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
486	      invoiceId = created?.id;
487	    }
488	  } catch (e) {
489	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
490	    throw e;
491	  }
492	  // A funded wallet is the referred user's first paid action — reward both sides.
493	  try {
494	    const { maybeRewardReferral } = await import("./actions-growth");
495	    await maybeRewardReferral(userId);
496	  } catch { /* best-effort */ }
497	  try {
498	    const u = await db.user.findUnique({ where: { id: userId } });
499	    if (u) {
500	      const { sendMail, emails } = await import("./mailer");
501	      // Say what the money was for. On a purchase leg it is emphatically NOT a
502	      // top-up, and a receipt that calls it one is the same false statement the
503	      // duplicate invoice used to make, just in the customer's inbox.
504	      // The third argument is the promise, and it is the truth: we claim an attached
505	      // invoice only when there is an invoice id to attach. A purchase leg issues no
506	      // top-up invoice (the order does), so its receipt points at billing history
507	      // instead of promising a file that was never generated.
508	      const tpl = emails.receipt(
509	        `$${(cents / 100).toFixed(2)}`,
510	        purchaseLeg ? "your Nxeon order" : "wallet top-up",
511	        !!invoiceId,
512	      );
513	      // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
514	      // A receipt is ACCOUNT tier — suppressible by email if the customer turned
515	      // account email off. This is the one send site where that toggle actually
516	      // bites today, so it is the one that made the switch a lie.
517	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt", invoiceId });
518	    }
519	  } catch { /* best-effort */ }
520	  return true;
521	}
