1	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
2	// success-redirect route and the webhook. Plain server module (not "use server").
3	//
4	// WHY THIS EXISTS (2026-07-25)
5	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
6	// whether `creditCheckoutSession()` returned true. That boolean is true only for
7	// the caller that won the race to insert the wallet credit — and the webhook
8	// calls the same function and discards the result. So:
9	//
10	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
11	//     `credited === false`, and the redirect quietly lands on an empty page.
12	//     $249 charged, $249 credited, no server, no error, no notification.
13	//   * Deterministic: the customer closes the tab before `success_url` resolves,
14	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
15	//
16	// Stripe's own guidance is explicit that a browser redirect must not be the
17	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
18	// its own marker, not a side effect of crediting — decides the single winner.
19	
20	import { db } from "./db";
21	import { classifyCheckoutSession, creditCheckoutSession, retrieveCheckoutSession } from "./stripe";
22	import { placeOrder } from "./order";
23	import { applyResize } from "./resize";
24	import { applyDiskExpand } from "./disk-expand";
25	
26	export type FulfilResult = {
27	  /** Where the browser should end up. The webhook ignores this. */
28	  redirect: string;
29	  /** True when THIS call performed the fulfilment work. */
30	  fulfilled: boolean;
31	  kind: "order" | "resize" | "diskExpand" | "topup" | "none";
32	  error?: string;
33	};
34	
35	/**
36	 * Claim exclusive responsibility for fulfilling `sessionId`.
37	 * Returns false when another caller already holds the claim — the UNIQUE index,
38	 * not a read-then-write check, is what makes this safe under concurrency.
39	 */
40	async function claim(sessionId: string, kind: string): Promise<boolean> {
41	  try {
42	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
43	    return true;
44	  } catch (e) {
45	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
46	    throw e;
47	  }
48	}
49	
50	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
51	  await db.fulfilledSession
52	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
53	    .catch(() => {});
54	}
55	
56	/**
57	 * Tell the customer their money is safe and someone knows. Called only on a path
58	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
59	 * outcome that is never acceptable.
60	 */
61	async function notifyStalled(userId: string) {
62	  await db.notification
63	    .create({
64	      data: {
65	        userId,
66	        title: "Payment received — we couldn't finish setting up your server",
67	        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
68	        href: "/dashboard/billing",
69	      },
70	    })
71	    .catch(() => {});
72	}
73	
74	/**
75	 * Credit the wallet and fulfil whatever the session was for, exactly once.
76	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
77	 *
78	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
79	 * defect found on 2026-07-27: this function used to ask three helpers for the
80	 * session, each of which swallowed every error into `null`, so a transient Stripe
81	 * failure was indistinguishable from "no purchase metadata" and fell through to
82	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
83	 * card charged with no server, no FulfilledSession row and no notification — and
84	 * because the webhook returns 200 either way, Stripe never retried it. A throw
85	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
86	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
87	 */
88	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
89	  // ONE retrieve, one view of the session, shared by the credit and the routing.
90	  const session = await retrieveCheckoutSession(sessionId);
91	  const purpose = classifyCheckoutSession(session);
92	
93	  // Nothing was paid (an abandoned session id, or one replayed before capture).
94	  // Never claim fulfilment for money that has not arrived.
95	  if (purpose.kind === "unpaid") {
96	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
97	  }
98	
99	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
100	  // transaction). We deliberately IGNORE its return value now — it reports who
101	  // won the credit race, which is not the same question as "has this been
102	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
103	  // race: the money has not reached the wallet, so nothing below may spend it.
104	  await creditCheckoutSession(session);
105	
106	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
107	  // it, so claim the session and record the failure exactly like a failed order:
108	  // reconcilable, and the customer is told. What it must NEVER become is a silent
109	  // wallet top-up, which is precisely what the old `null` fall-through produced.
110	  if (purpose.kind === "unreadable") {
111	    if (await claim(sessionId, "unreadable")) {
112	      await settle(sessionId, "FAILED", purpose.detail);
113	      if (purpose.userId) await notifyStalled(purpose.userId);
114	    }
115	    return {
116	      redirect: `${base}/dashboard/billing?paid=1`,
117	      fulfilled: false,
118	      kind: "none",
119	      error: purpose.detail,
120	    };
121	  }
122	
123	  const order = purpose.kind === "order" ? purpose : null;
124	  if (order) {
125	    if (!(await claim(sessionId, "order"))) {
126	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
127	    }
128	    try {
129	      const user = await db.user.findUnique({ where: { id: order.userId } });
130	      if (!user) throw new Error("user not found for paid order");
131	      // Settle the price stamped on the session BEFORE the card was charged — never
132	      // a fresh quote taken now. The customer has already paid the card leg of that
133	      // exact total; re-pricing here and taking the difference out of the wallet is
134	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
135	      // the resize and disk-expand branches below, which have always passed the
136	      // amount through metadata for this reason.
137	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
138	      // per-IP cap can't be enforced here — the per-account unique still holds, and
139	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
140	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
141	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
142	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
143	      // round-trip even in the webhook (no cookies).
144	      const serverId = await placeOrder(user, order.intent, order.sold, {
145	        ipHash: null,
146	        campaign: order.campaign,
147	        promoReservationToken: order.promoReservationToken,
148	      });
149	      await settle(sessionId, "DONE", serverId);
150	      return { redirect: `${base}/dashboard/servers/${serverId}`, fulfilled: true, kind: "order" };
151	    } catch (e) {
152	      // Payment is captured and the funds are in the wallet — record the failure
153	      // so it is reconcilable rather than invisible, and tell the customer.
154	      const msg = String((e as Error)?.message ?? e);
155	      await settle(sessionId, "FAILED", msg);
156	      await notifyStalled(order.userId);
157	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
158	    }
159	  }
160	
161	  const resize = purpose.kind === "resize" ? purpose : null;
162	  if (resize) {
163	    const back = `${base}/dashboard/servers/${resize.serverId}`;
164	    if (!(await claim(sessionId, "resize"))) {
165	      return { redirect: back, fulfilled: false, kind: "resize" };
166	    }
167	    try {
168	      await applyResize({
169	        serverId: resize.serverId,
170	        planId: resize.planId,
171	        actorUserId: resize.userId,
172	        chargeCents: resize.chargeCents,
173	      });
174	      await settle(sessionId, "DONE", resize.serverId);
175	      return { redirect: back, fulfilled: true, kind: "resize" };
176	    } catch (e) {
177	      const msg = String((e as Error)?.message ?? e);
178	      await settle(sessionId, "FAILED", msg);
179	      await notifyStalled(resize.userId);
180	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
181	    }
182	  }
183	
184	  const expand = purpose.kind === "diskExpand" ? purpose : null;
185	  if (expand) {
186	    const back = `${base}/dashboard/servers/${expand.serverId}`;
187	    if (!(await claim(sessionId, "diskExpand"))) {
188	      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
189	    }
190	    try {
191	      await applyDiskExpand({
192	        serverId: expand.serverId,
193	        addGB: expand.addGB,
194	        actorUserId: expand.userId,
195	        chargeCents: expand.chargeCents,
196	      });
197	      await settle(sessionId, "DONE", expand.serverId);
198	      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
199	    } catch (e) {
200	      const msg = String((e as Error)?.message ?? e);
201	      await settle(sessionId, "FAILED", msg);
202	      await notifyStalled(expand.userId);
203	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
204	    }
205	  }
206	
207	  // Plain wallet top-up: crediting above is the whole job. Reached ONLY when the
208	  // session genuinely carried no purchase metadata — never because we failed to
209	  // read it (that throws) and never because we failed to parse it ("unreadable").
210	  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
211	}
