1	import { NextRequest, NextResponse } from "next/server";
2	import { stripe, stripeConfigured } from "@/lib/stripe";
3	import { fulfilCheckoutSession } from "@/lib/fulfil-checkout";
4	import { releaseReservation } from "@/lib/promo-redemption";
5	import type Stripe from "stripe";
6	
7	export async function POST(req: NextRequest) {
8	  if (!stripeConfigured() || !process.env.STRIPE_WEBHOOK_SECRET) {
9	    return NextResponse.json({ error: "not configured" }, { status: 400 });
10	  }
11	  const sig = req.headers.get("stripe-signature");
12	  if (!sig) return NextResponse.json({ error: "missing signature" }, { status: 400 });
13	  const raw = await req.text();
14	
15	  let event;
16	  try {
17	    event = stripe().webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET);
18	  } catch {
19	    return NextResponse.json({ error: "invalid signature" }, { status: 400 });
20	  }
21	
22	  if (event.type === "checkout.session.completed") {
23	    const session = event.data.object as { id: string };
24	    // FULFIL, don't just credit. This used to call `creditCheckoutSession` and
25	    // throw the result away, which meant the webhook credited the wallet and then
26	    // — by winning the race — caused the success-redirect to see `credited: false`
27	    // and skip provisioning entirely. The webhook is the reliable signal (the
28	    // redirect may never happen at all), so it must be able to fulfil on its own.
29	    // `fulfilCheckoutSession` is idempotent via UNIQUE(FulfilledSession), so the
30	    // two callers racing is safe: exactly one does the work.
31	    //
32	    // Errors are swallowed deliberately — returning non-2xx makes Stripe retry the
33	    // event, and the failure is already recorded on the FulfilledSession row and
34	    // surfaced to the customer.
35	    try {
36	      await fulfilCheckoutSession(session.id);
37	    } catch (e) {
38	      console.error("[stripe-webhook] fulfil failed", session.id, e);
39	    }
40	  }
41	
42	  // A checkout the customer never completed: Stripe expires it (we cap the payable
43	  // window at ORDER_CHECKOUT_EXPIRES_MS). RELEASE any first-month-free hold it carried
44	  // so the customer's one-time offer is returned promptly rather than waiting for the
45	  // worker sweep. Guarded to RESERVED, so a completed+confirmed grant is never revoked.
46	  // (If this event type isn't enabled in the Stripe dashboard, the worker sweep is the
47	  // backstop — the hold's reservedUntil has passed by the time the session expires.)
48	  if (event.type === "checkout.session.expired") {
49	    const session = event.data.object as Stripe.Checkout.Session;
50	    const token = session.metadata?.nxeonPromoReservation;
51	    if (token) {
52	      try {
53	        await releaseReservation(token);
54	      } catch (e) {
55	        console.error("[stripe-webhook] release reservation failed", token, e);
56	      }
57	    }
58	  }
59	
60	  return NextResponse.json({ received: true });
61	}
