245	export async function login(
246	  prev: any,
247	  formData: FormData,
248	): Promise<{ error?: string; needs2fa?: boolean }> {
249	  const parsed = credsSchema.safeParse({
250	    // Same canonical form the account was stored under (lib/email-normalize.ts).
251	    // Without this, signing in as `Alice@Example.com` missed a row stored as
252	    // `alice@example.com` and reported bad credentials for a correct password.
253	    email: normalizeEmail(formData.get("email")),
254	    password: formData.get("password"),
255	  });
256	  if (!parsed.success) return { error: "Invalid email or password." };
257	
258	  // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
259	  // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
260	  //
261	  // The IP comes from `clientIp` (lib/rate-limit.ts), NEVER from
262	  // `x-forwarded-for.split(",")[0]`. nginx forwards the header with
263	  // `$proxy_add_x_forwarded_for`, which APPENDS the peer it saw to whatever the
264	  // client sent — so the leftmost entry is a free-text field the caller filled
265	  // in, and keying on it meant an attacker could rotate one header value per
266	  // request and never bind this limiter at all. That is the limiter standing
267	  // between a known email address and unlimited password guesses, and (below)
268	  // unlimited 2FA code guesses once a password is known. See the docblock on
269	  // `clientIp` for the measurement.
270	  const rlId = `${parsed.data.email}:${clientIp(await headers())}`;
271	  const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
272	  const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
273	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
274	
275	  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
276	  // ALWAYS spend one bcrypt comparison, even when the address does not exist.
277	  //
278	  // `!user || !(await bcrypt.compare(...))` short-circuits: with no account, bcrypt
279	  // never ran. The reply text was correctly identical either way, but the reply
280	  // TIME was not — bcrypt at cost 12 is ~250ms against a single indexed SELECT, a
281	  // gap one sample per address is enough to read. That turns the login form into
282	  // an account-enumeration oracle: "does this person bank here", answered for any
283	  // address, at scale, without ever guessing a password.
284	  //
285	  // It was materially worse while the throttle above was keyed on the
286	  // caller-supplied first hop of `x-forwarded-for`, because the rate limit that
287	  // would otherwise cap sampling could itself be stepped around per request. That
288	  // is fixed, but a defence that only works because another defence works is not
289	  // one, so the timing is equalised on its own terms.
290	  //
291	  // The comparison against DUMMY_HASH is discarded — it exists solely to spend the
292	  // same ~250ms. Keep the reply string identical to the wrong-password case.
293	  const passwordOk = user
294	    ? await bcrypt.compare(parsed.data.password, user.passwordHash)
295	    : ((await bcrypt.compare(parsed.data.password, DUMMY_PASSWORD_HASH)), false);
296	  // `!user` is repeated here purely so TypeScript narrows `user` for the code
297	  // below. It is NOT a short-circuit any more: `passwordOk` above has already
298	  // spent the bcrypt comparison in both branches, which is the whole point.
299	  if (!user || !passwordOk) {
300	    return { error: "Invalid email or password." };
301	  }
302	  if (user.suspended) return { error: "This account is suspended." };
303	
304	  // Two-factor challenge, if enabled on the account.
305	  if (user.totpEnabled) {
306	    const code = String(formData.get("code") ?? "").trim();
307	    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
308	    if (!(await verifyTotpForUser(user.id, code))) {
309	      return { error: "Invalid 2FA code.", needs2fa: true };
310	    }
311	  }
312	
313	  resetRateLimit(`login:${rlId}`);
314	  await audit(user.id, "user.login");
315	  await createSession(user.id);
316	  // Land where they were HEADING, not on a generic dashboard.
317	  //
318	  // Public CTAs like "Migrate free →" send a logged-out visitor into
319	  // /dashboard/..., which bounces to /login and — until now — discarded what they
320	  // clicked. They signed in and arrived somewhere unrelated, with no route back to
321	  // the thing they wanted. Seven CTAs did this, the worst being "Contact support"
322	  // on the PUBLIC help page, where a prospect met a login wall instead of /contact.
323	  //
324	  // `safeNext` only ever returns a path on THIS site (see its definition): an
325	  // open redirect on a login form is a phishing primitive, so an absolute URL, a
326	  // protocol-relative `//evil.test` or anything that is not a single-slash path is
327	  // discarded rather than sanitised.
328	  const next = safeNext(formData.get("next"));
329	  redirect(next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
330	}
