430	/**
431	 * Grace added to a first-month-free hold's lifetime beyond the Checkout session's
432	 * payable window, so a payment landing at the very last instant still finds a live
433	 * hold to confirm. The `checkout.session.expired` webhook and the worker sweep only
434	 * reap holds past this, i.e. well after the session can no longer be paid.
435	 */
436	const RESERVATION_GRACE_MS = 10 * 60 * 1000;
437	
438	export async function payAndDeploy(
439	  prev: any,
440	  formData: FormData,
441	): Promise<{ error?: string; checkoutUrl?: string }> {
442	  const user = await requireUser();
443	  // Spend path: never move a customer's money while an admin is impersonating them.
444	  await assertNotImpersonating();
445	  // Same verification gate every purchase path applies. This is the CARD path, so it is the
446	  // one where an unreachable address is most expensive: without it we would take
447	  // a real payment for a machine whose credentials have nowhere to go.
448	  const unverified = await emailVerificationError(user);
449	  if (unverified) return { error: unverified };
450	  // Per-user server cap — the same one `orderGameServer` enforces for game tiers.
451	  const limitErr = await serverLimitError(user.id);
452	  if (limitErr) return { error: limitErr };
453	  const intent = intentFromFormData(formData);
454	
455	  let quote;
456	  try {
457	    quote = await orderQuote(intent);
458	  } catch (e) {
459	    if (e instanceof OrderError) return { error: e.message };
460	    throw e;
461	  }
462	
463	  // Managed first-month-free eligibility. If this account/IP has ALREADY redeemed
464	  // the promo (or it's switched off), re-quote at FULL price so the wallet split,
465	  // the card leg and the stamped total are all full — the free month is a
466	  // once-per-person offer. The wallet path is self-correcting regardless (its
467	  // atomic claim inside placeOrder charges full on a lost claim), but the CARD
468	  // leg settles up front, so it MUST be priced full here or a repeat customer
469	  // gets a second discounted checkout. This mirrors the coupon guard below.
470	  // `|| null` matters: hashIp returns "" when the IP is unavailable, and an empty
471	  // string is a REAL value to the (promoId, ipHash) unique — it would collide
472	  // across every IP-less redemption and wrongly block them. NULLs are distinct.
473	  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
474	  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
475	    quote = await orderQuote(intent, { suppressPromo: true });
476	  }
477	  const promoCampaign = promoCampaignFromCookie(await cookies());
478	
479	  const isAdmin = user.role === "ADMIN";
480	  const freePath = !!intent.free && isAdmin;
481	
482	  // Wallet-aware split. The customer's Review screen computes the exact same split
483	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
484	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
485	  // the balance. Free admin grants skip the split entirely (no money moves).
486	  const useWallet = formData.get("useWallet") !== "0";
487	  // `let`: a first-month-free hold lost to a concurrent checkout forces a full-price
488	  // re-quote below, which changes the split. Free admin grants skip it entirely.
489	  let { walletApplied, cardCents } = freePath
490	    ? { walletApplied: 0, cardCents: 0 }
491	    : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });
492	
493	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
494	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
495	  // (or nothing, for a free grant); the balance check inside it holds because a
496	  // $0 card portion means balance >= chargeCents.
497	  if (freePath || cardCents <= 0) {
498	    let serverId: string;
499	    try {
500	      // Reuse the request-scoped IP hash computed above so placeOrder can enforce
501	      // both the coupon's once-per-person guard and the first-month-free 1/IP cap.
502	      serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
503	    } catch (e) {
504	      if (e instanceof OrderError) return { error: e.message };
505	      throw e;
506	    }
507	    redirect(`/dashboard/servers/${serverId}`);
508	  }
509	
510	  // Coupon guard for the CARD path. The wallet path is already safe — its
511	  // placeOrder claim throws and we surface it above (nothing charged). But the
512	  // card leg below discounts `cardCents` up front and settles the redemption only
513	  // AFTER the card clears, where a failed claim is swallowed so a paid provision
514	  // isn't stranded. So a customer who already used a one-per-person code would
515	  // still get the discounted charge. Re-run the per-person guards as reads here
516	  // and refuse before checkout — same messages the wallet path would show.
517	  if (quote.couponId) {
518	    const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon");
519	    const claimable = await orderCouponClaimable({
520	      couponId: quote.couponId,
521	      firstTimeOnly: quote.couponFirstTimeOnly,
522	      maxRedemptions: quote.couponMaxRedemptions,
523	      userId: user.id,
524	      ipHash,
525	    });
526	    if (!claimable.ok) return { error: `${claimable.error} Remove the code to continue at the regular price.` };
527	  }
528	
529	  // RESERVE the first-month-free credit BEFORE opening the Checkout session. This is
530	  // the money-race fix: the card leg settles the discounted price up front, so unless
531	  // this account/IP's one credit is held EXCLUSIVELY here, two concurrent card
532	  // checkouts could each pass eligibility and each collect a free month from one
533	  // eligibility. The reserve's INSERT contends on the same two unique constraints as
534	  // the grant, so exactly one checkout holds it; a loser re-quotes at FULL price so
535	  // its stamped total, card leg and settlement all agree (displayed === charged). The
536	  // hold is CONFIRMED at fulfilment, RELEASED on `checkout.session.expired`, and
537	  // swept as a backstop — an abandoned checkout never permanently burns the offer.
538	  //
539	  // `promoCreditCents > 0` is the honest "this quote carries the free month" signal
540	  // (0 whenever the promo is off, already-redeemed via the re-quote above, or the
541	  // product is out of scope — firstMonthFreeAppliesTo). It is 0 for VPS today, so
542	  // this block is inert for VPS and correct the moment the owner extends the promo to
543	  // any card-checkout product.
544	  let promoReservationToken: string | null = null;
545	  if (quote.promoCreditCents > 0) {
546	    const reservedUntil = new Date(Date.now() + ORDER_CHECKOUT_EXPIRES_MS + RESERVATION_GRACE_MS);
547	    const res = await reserveFirstMonthFree({
548	      userId: user.id,
549	      ipHash: promoIpHash,
550	      serviceType: "VPS",
551	      campaign: promoCampaign,
552	      chargedCents: quote.chargeCents,
553	      reservedUntil,
554	    });
555	    if (res.reserved) {
556	      promoReservationToken = res.token;
557	    } else {
558	      // Lost the race (this account/IP already holds or redeemed the credit): re-quote
559	      // at FULL price and recompute the split so the card leg is the real full amount.
560	      quote = await orderQuote(intent, { suppressPromo: true });
561	      ({ walletApplied, cardCents } = walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet }));
562	      // A full-price re-quote can be fully wallet-covered — provision immediately (its
563	      // own atomic claim inside placeOrder will correctly charge full on a lost claim).
564	      if (cardCents <= 0) {
565	        let serverId: string;
566	        try {
567	          serverId = await placeOrder(user, intent, null, { ipHash: promoIpHash, campaign: promoCampaign });
568	        } catch (e) {
569	          if (e instanceof OrderError) return { error: e.message };
570	          throw e;
571	        }
572	        redirect(`/dashboard/servers/${serverId}`);
573	      }
574	    }
575	  }
576	
577	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
578	  // On payment success the confirm route credits this card amount to the wallet and
579	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
580	  // `walletApplied` and the card the rest — the wallet is never touched before the
581	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
582	  // so it needs no separate metadata field.)
583	  // The price is handed over EXPLICITLY, from the very quote the wallet split above
584	  // was computed from. Without this argument `createOrderCheckout` re-quotes
585	  // internally, microseconds later, from its own `new Date()` — the same function,
586	  // so no formula can drift, but two different instants. A promo boundary (or an
587	  // operator changing a plan price) falling between them would mean the card leg
588	  // and the stamped total were priced against two different worlds, and the wallet
589	  // would silently absorb the difference. One quote, one price, one charge.
590	  // If opening the session fails after we reserved, RELEASE the hold so the customer
591	  // never loses their offer to a checkout that never came into being.
592	  let url: string | null;
593	  try {
594	    url = await createOrderCheckout(user, cardCents, intent, orderPriceOf(quote), promoCampaign, promoReservationToken);
595	  } catch (e) {
596	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
597	    throw e;
598	  }
599	  if (!url) {
600	    if (promoReservationToken) await releaseReservation(promoReservationToken).catch(() => {});
601	    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
602	  }
603	  return { checkoutUrl: url };
604	}
