608	async function ownedServer(serverId: string) {
609	  const user = await requireUser();
610	  const server = await db.server.findUnique({ where: { id: serverId } });
611	  if (!server) throw new Error("Not found");
612	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
613	  return { user, server };
614	}
