616	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
617	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
618	  // can render it — a `throw` here reaches the browser as Next's redacted generic
619	  // error, discarding the specific, actionable message (e.g. "Delete your data
620	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
621	  const { user, server } = await ownedServer(serverId);
622	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
623	    start: "START",
624	    stop: "STOP",
625	    reboot: "REBOOT",
626	    reinstall: "REINSTALL",
627	    delete: "DELETE",
628	  };
629	  const type = allowed[action];
630	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
631	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
632	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
633	  }
634	
635	  // A reinstall wipes the whole VM, including any block-storage volume the VM
636	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
637	  //
638	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
639	  // deliberately keeps `serverId` set so the volume can be re-attached
640	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
641	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
642	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
643	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
644	  // Reinstall — both guards see zero attached volumes, and the purge takes the
645	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
646	  // by serverId; this path did not. That asymmetry was the bug.
647	  if (type === "REINSTALL") {
648	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
649	    if (pinnedVolumes > 0) {
650	      return {
651	        error:
652	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
653	      };
654	    }
655	  }
656	
657	  const pending = await db.job.count({
658	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
659	  });
660	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
661	  // with no explanation. Tell them why.
662	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
663	
664	  if (type === "DELETE") {
665	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
666	  }
667	  await db.job.create({ data: { type, serverId } });
668	  await audit(user.id, `server.${action}`, serverId);
669	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
670	  revalidatePath(`/dashboard/servers/${serverId}`);
671	}
