673	// ---------- Wallet (demo top-up until a payment gateway is connected) ----------
674	
675	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
676	  const user = await requireUser();
677	  // Spend/credit path: block while impersonating so an admin can't mint or move
678	  // a customer's balance on their behalf.
679	  await assertNotImpersonating();
680	  // Security: never mint free wallet balance in production. The demo gateway that
681	  // credits without a real payment is only ever acceptable in non-production, and
682	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
683	  if (process.env.NODE_ENV === "production") {
684	    return { error: "Please add funds with a card via the secure checkout." };
685	  }
686	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
687	  // go through Checkout.
688	  const { stripeConfigured } = await import("./stripe");
689	  if (stripeConfigured()) {
690	    return { error: "Please add funds with a card via the secure checkout." };
691	  }
692	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
693	  const topupIp = clientIp(await headers());
694	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
695	  if (!topupRl.ok) {
696	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
697	  }
698	  const amount = Number(formData.get("amount"));
699	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
700	    return { error: "Amount must be between $1 and $1000." };
701	  }
702	  const cents = Math.round(amount * 100);
703	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
704	  const minTopup = await getSettingInt("min_topup_cents", 500);
705	  if (cents < minTopup) {
706	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
707	  }
708	
709	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
710	  // sets. applyCouponToTopup re-validates for this user against the real amount.
711	  const jar = await cookies();
712	  const couponCode = jar.get(COUPON_COOKIE)?.value?.trim();
713	  let bonusCents = 0;
714	  let couponId: string | null = null;
715	  let couponLabel = "";
716	  if (couponCode) {
717	    const result = await applyCouponToTopup(couponCode, cents);
718	    if (result.ok) {
719	      bonusCents = result.bonusCents;
720	      couponId = result.couponId;
721	      couponLabel = result.label;
722	    } else {
723	      // REFUSE, don't silently drop. The old code fell through and completed the
724	      // top-up with no bonus and no message, so a code that passed validation at
725	      // the preview amount but fails against the real one (a `minAmountCents`
726	      // floor, an exhausted limit, an expiry) simply vanished — the customer paid
727	      // expecting a bonus and got nothing, with nowhere to look. Nothing has been
728	      // charged at this point, so stopping is free and the customer can retry
729	      // without the code or with a larger amount.
730	      return {
731	        error:
732	          `${result.error ?? "That promo code can't be applied to this amount."} ` +
733	          `Nothing has been charged — adjust the amount or remove the code and try again.`,
734	      };
735	    }
736	  }
737	
738	  try {
739	    await db.$transaction(async (tx) => {
740	      // Claim the coupon FIRST, atomically. The old code did an unconditional
741	      // `coupon.update({ timesRedeemed: { increment: 1 } })` after a plain read of
742	      // the cap in the preview, so two top-ups racing for the last slot both saw
743	      // room and both incremented — the limit could be blown past by any number of
744	      // concurrent claims. Mirror `claimOrderCoupon`: a conditional `updateMany`
745	      // gated on `timesRedeemed < max` is the only thing that atomically hands out
746	      // the final slot, and the unique(coupon,user) create fails a double-claim.
747	      if (bonusCents > 0 && couponId) {
748	        const c = await tx.coupon.findUnique({ where: { id: couponId }, select: { maxRedemptions: true } });
749	        const claim = await tx.coupon.updateMany({
750	          where:
751	            c?.maxRedemptions == null
752	              ? { id: couponId, active: true }
753	              : { id: couponId, active: true, timesRedeemed: { lt: c.maxRedemptions } },
754	          data: { timesRedeemed: { increment: 1 } },
755	        });
756	        if (claim.count !== 1) throw new CouponClaimError("That code has just reached its redemption limit.");
757	        try {
758	          await tx.couponRedemption.create({
759	            data: { couponId, userId: user.id, amountCents: bonusCents, context: "topup" },
760	          });
761	        } catch {
762	          throw new CouponClaimError("You’ve already used this code.");
763	        }
764	      }
765	      await tx.user.update({
766	        where: { id: user.id },
767	        data: { balanceCents: { increment: cents + bonusCents } },
768	      });
769	      await tx.walletTransaction.create({
770	        data: { userId: user.id, amountCents: cents, description: "Wallet top-up (demo gateway)" },
771	      });
772	      if (bonusCents > 0 && couponId) {
773	        await tx.walletTransaction.create({
774	          data: {
775	            userId: user.id,
776	            amountCents: bonusCents,
777	            description: `Promo ${couponCode!.toUpperCase()} — ${couponLabel}`,
778	          },
779	        });
780	      }
781	    });
782	  } catch (e) {
783	    // The demo gateway charges nothing external, so a rolled-back transaction
784	    // means the customer is untouched — safe to surface and let them retry.
785	    if (e instanceof CouponClaimError) {
786	      return { error: `${e.message} Nothing has been charged — remove the code and try again.` };
787	    }
788	    throw e;
789	  }
790	  jar.delete(COUPON_COOKIE);
791	  await audit(user.id, "wallet.topup", `$${amount}${bonusCents > 0 ? ` +bonus $${(bonusCents / 100).toFixed(2)}` : ""}`);
792	  // First successful paid action may unlock a referral reward for both parties.
793	  try {
794	    await maybeRewardReferral(user.id);
795	  } catch { /* non-fatal */ }
796	  revalidatePath("/dashboard/billing");
797	  return {};
798	}
