813	export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
814	  // Spend path: block wallet debits while an admin is impersonating.
815	  await assertNotImpersonating();
816	  const { user, server } = await ownedServer(serverId);
817	  if (server.isFree || !server.expiresAt) return;
818	  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
819	  // cannot strand an existing customer: every account that owns a server today
820	  // predates verification and is grandfathered, and the automatic renewal in
821	  // worker/billing.ts does not pass through here at all — nobody's server lapses
822	  // because of this check.
823	  const unverified = await emailVerificationError(user);
824	  if (unverified) return { error: unverified };
825	  const plan = await db.plan.findUnique({ where: { id: server.planId } });
826	  if (!plan) return;
827	  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
828	  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
829	  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
830	  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
831	  const gamePlan = server.gamePlanId
832	    ? await db.gamePlan.findUnique({
833	        where: { id: server.gamePlanId },
834	        select: { name: true, priceCents: true, termMonths: true },
835	      })
836	    : null;
837	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
838	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
839	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
840	    where: { serverId }, select: { id: true },
841	  }));
842	  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
843	  // in worker/billing.ts and the saved-card path use. Not a second copy of the
844	  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
845	  // rule, the second of which was a fresh duplicate written hours after the first.
846	  const quote = renewalQuote(
847	    {
848	      termMonths: server.termMonths,
849	      extraDiskGB: server.extraDiskGB,
850	      plan: { name: plan.name, priceCents: plan.priceCents },
851	      gamePlan,
852	      dedicatedIp: hasDedicatedIp ? {} : null,
853	      backupTier: server.backupTier,
854	    },
855	    {
856	      ipMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
857	      extraDiskPerGbCents: await extraDiskPerGbCents(),
858	      backupPlusCents: await backupPlusMonthlyCents(),
859	      annualDiscountPct: await annualDiscountPct(),
860	    },
861	  );
862	  const renewCents = quote.totalCents;
863	  const term = { months: quote.months };
864	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
865	  const extraDiskCents = gamePlan ? 0 : extraDiskMonthly * quote.months;
866	  const owner = await db.user.findUnique({ where: { id: server.userId } });
867	  if (!owner || owner.balanceCents < renewCents) {
868	    return { error: "Insufficient balance — top up your wallet first." };
869	  }
870	
871	  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
872	  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
873	  // can't both read E, both debit, and both write E+term (double-charge, one
874	  // term granted). Only the CAS that matches E wins; the loser is a no-op.
875	  const E = server.expiresAt;
876	  const base = new Date(Math.max(E.getTime(), Date.now()));
877	  const newExpiry = addMonths(base, term.months);
878	
879	  // `renewCents` above is `vpsTermPriceCents(...)` — the REGULAR price, with no
880	  // seasonal promo applied. That is exactly what lib/promotions.ts promises: the
881	  // strikethrough on the marketing page is the real renewal price. So the months
882	  // being added here are sold at 0% off, and the term's stored rate has to say so.
883	  //
884	  // BLENDED, not overwritten. A customer can renew early, stacking a full-price
885	  // term on top of months still running at an intro discount. Overwriting would
886	  // silently reprice those earlier months to full list — and that is the profitable
887	  // direction: buy 36 months at 45% off, renew once at full price, and every one of
888	  // the original discounted months would suddenly credit at the full rate on a
889	  // downgrade. Blending keeps the cash value of the window invariant.
890	  const renewedPercent = prorateBlendPercent({
891	    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
892	    currentMonths: remainingMonths(E, Date.now()),
893	    addedPercent: 0,
894	    addedMonths: term.months,
895	  });
896	  try {
897	    await db.$transaction(async (tx) => {
898	      // Compare-and-swap the expiry first; if it no longer equals E another
899	      // renewal already advanced it — bail without charging (tx rolls back).
900	      const adv = await tx.server.updateMany({
901	        where: { id: serverId, expiresAt: E },
902	        data: {
903	          expiresAt: newExpiry,
904	          termPromoPercent: renewedPercent,
905	          suspendedNote: null,
906	          suspendReason: null,
907	        },
908	      });
909	      if (adv.count === 0) throw new AlreadyRenewedError();
910	      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
911	      await debitWallet(tx, server.userId, renewCents);
912	      await tx.walletTransaction.create({
913	        data: {
914	          userId: server.userId,
915	          amountCents: -renewCents,
916	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
917	        },
918	      });
919	      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
920	      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
921	      await tx.invoice.create({
922	        data: invoiceCreateData({
923	          userId: server.userId,
924	          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
925	          status: "PAID",
926	          period: { start: E, end: newExpiry },
927	          lineItems: [
928	            {
929	              description: `${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
930	              qty: 1,
931	              unitCents: renewCents - extraDiskCents,
932	              amountCents: renewCents - extraDiskCents,
933	            },
934	            ...(extraDiskCents > 0
935	              ? [
936	                  {
937	                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
938	                    qty: 1,
939	                    unitCents: extraDiskCents,
940	                    amountCents: extraDiskCents,
941	                  },
942	                ]
943	              : []),
944	          ],
945	        }),
946	      });
947	    });
948	  } catch (e) {
949	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
950	    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
951	    throw e;
952	  }
953	  await audit(user.id, "server.renew_now", serverId);
954	
955	  // An UNPAID-suspended server springs back to life once paid — but only that
956	  // kind. This used to fire for ANY suspended server, so a customer suspended for
957	  // outbound abuse could click "Renew now", pay, and put themselves straight back
958	  // on the network, undoing an abuse or admin action with a card. Legacy rows with
959	  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
960	  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
961	    const pending = await db.job.count({
962	      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
963	    });
964	    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
965	  }
966	  revalidatePath(`/dashboard/servers/${serverId}`);
967	}
