1	// Shared server-upgrade (RESIZE up) core — used by the wallet flow
2	// (lib/actions-server.ts resizeServer) and by the Stripe confirm route so a paid
3	// checkout can apply the upgrade immediately. Plain server module (not "use server").
4	import { db } from "./db";
5	import { debitWallet, InsufficientBalanceError } from "./wallet";
6	import { invoiceCreateData } from "./invoices";
7	import { prorateUpgradeCents, remainingMonths } from "./proration";
8	import { annualDiscountPct } from "./annual-discount";
9	
10	/**
11	 * Average calendar month in ms — RE-EXPORTED from lib/proration.ts, never
12	 * redeclared.
13	 *
14	 * It used to be its own `30.44 * 86400_000` here, a byte-identical twin of the one
15	 * in lib/proration.ts, and lib/disk-expand.ts imported THIS copy while every other
16	 * proration read the other. Two constants that happen to be equal are still two
17	 * constants: the day someone tunes one (to 365/12, or to a real calendar month) the
18	 * disk-expansion charge and the plan-resize charge quietly start pricing the same
19	 * remaining term differently. This file's whole history is second copies of a
20	 * number drifting, so there is one and it lives with the proration maths.
21	 */
22	export { MS_PER_AVG_MONTH } from "./proration";
23	
24	export class ResizeError extends Error {}
25	
26	type QuotedServer = Awaited<ReturnType<typeof loadServer>>;
27	type QuotedPlan = NonNullable<Awaited<ReturnType<typeof loadPlan>>>;
28	
29	function loadServer(serverId: string) {
30	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
31	}
32	function loadPlan(planId: string) {
33	  return db.plan.findUnique({ where: { id: planId } });
34	}
35	
36	export type ResizeQuote = {
37	  server: NonNullable<QuotedServer>;
38	  newPlan: QuotedPlan;
39	  prorateCents: number;
40	};
41	
42	/**
43	 * Validate an UPGRADE and compute the prorated charge over the ACTUAL remaining
44	 * duration (monthly price difference for every remaining month; null expiresAt
45	 * on free/admin servers => 0). Throws ResizeError with a user-facing message on
46	 * any guard failure. Does NOT check ownership — callers must do that.
47	 *
48	 * ─── INTERACTION WITH PER-SERVER EXTRA DISK ─────────────────────────────────
49	 * `Server.extraDiskGB` (disk bought via the deploy upsell or "Add storage") is
50	 * ADDITIVE to whichever plan the server is on, so a plan change must leave it
51	 * completely alone. Two things follow, and both are deliberate:
52	 *
53	 *  1. NOT DOUBLE-CHARGED. The proration below is a difference of PLAN monthly
54	 *     prices. The extra-disk surcharge is identical before and after the resize
55	 *     (same GB, same per-GB price), so it cancels out of the delta exactly — it
56	 *     must never be added here. It keeps being billed, unchanged, by the renewal
57	 *     sweep, which reads `extraDiskGB` directly.
58	 *  2. NOT LOST. Nothing in the resize path writes `extraDiskGB`, and the worker's
59	 *     RESIZE handler sizes the disk to `newPlan.diskGB + server.extraDiskGB` — so
60	 *     the customer keeps every GB they paid for. (Sizing to the bare plan disk
61	 *     would ask Proxmox to SHRINK the disk of any server holding extra storage,
62	 *     and the whole resize would hard-fail.)
63	 *
64	 * The disk-grow guard below intentionally compares PLAN disks, not effective
65	 * disks: since the extra is added to both sides, a target plan with an equal or
66	 * larger disk can never shrink the effective disk.
67	 */
68	export async function resizeQuote(serverId: string, planId: string): Promise<ResizeQuote> {
69	  const server = await loadServer(serverId);
70	  if (!server) throw new ResizeError("Not found");
71	  const newPlan = await loadPlan(planId);
72	  if (!newPlan?.active) throw new ResizeError("Plan not available.");
73	  if (newPlan.id === server.planId) throw new ResizeError("Server is already on this plan.");
74	  // A GAME server is not priced from `plan` at all, so it cannot be prorated
75	  // against it.
76	  //
77	  // Game tiers carry BOTH a base `planId` and a `gamePlanId`, and are sold at
78	  // `gamePlan.priceCents` — a FLAT, all-in price, typically LOWER than the base
79	  // plan they run on. The live row: `minecraft-mm8w85` sold at $4.99 on a Starter
80	  // base plan of $8.99. `renewalCharge` already treats a game plan as all-in with
81	  // no add-on lines; every proration path read `server.plan.priceCents` and was
82	  // blind to it.
83	  //
84	  // The dangerous direction is the CREDIT. lib/proration.ts rests on one
85	  // invariant — a prorated credit is strictly less than the cash actually
86	  // collected for those months — and that is the whole argument in
87	  // `resolveTermPromoPercent`. A tier sold at $9.99/mo flat on a $20.99 base plan
88	  // credits $20.99-worth per remaining month on a downgrade: real wallet money the
89	  // customer never paid, self-service.
90	  //
91	  // Today it is blocked only by the disk-monotonic guard below — in a catalogue
92	  // where price and disk both rise, no cheaper plan has equal-or-larger disk. That
93	  // is a coincidence of the current price list, not a protection; one cheap
94	  // high-disk plan opens it. lib/proration.ts's header calls out exactly this shape
95	  // about the pre-2026-07-25 bug, so it is refused explicitly rather than left
96	  // resting on an unrelated guard.
97	  if (server.gamePlanId) {
98	    throw new ResizeError(
99	      "Game server plans are fixed bundles — switch tiers from the game server's own settings, or contact support.",
100	    );
101	  }
102	  if (newPlan.diskGB < server.plan.diskGB) {
103	    throw new ResizeError("Disk storage can only grow — choose a plan with equal or larger disk.");
104	  }
105	  if (newPlan.priceCents < server.plan.priceCents) {
106	    throw new ResizeError("Downgrades aren't self-service yet — please contact support.");
107	  }
108	  if (!["RUNNING", "STOPPED"].includes(server.status)) throw new ResizeError("Server is busy.");
109	
110	  let prorateCents = 0;
111	  if (!server.isFree && server.expiresAt) {
112	    // Price the upgrade at the term discount AND the rate THIS SERVER'S TERM WAS
113	    // SOLD AT (`server.termPromoPercent`, persisted at every point a term is
114	    // bought). Using the raw list-price delta (as this did until 2026-07-25)
115	    // overcharged by the whole discount stack: on a 36-month term with a 30% promo
116	    // running, $1,044.45 to upgrade versus $665.08 to simply buy the same plan
117	    // outright for the same end date. Pricing off `currentPromo(now)` instead (as
118	    // it did until 2026-07-26) was worse: the customer picked the rate by picking
119	    // the date, upgrading under Cyber Monday's 45% and downgrading under the 15%
120	    // Launch Sale to pocket the spread. Shared with the downgrade credit and with
121	    // the client picker via lib/proration.ts so displayed, charged and credited
122	    // cannot drift apart.
123	    //
124	    // `remainingMonths` covers EVERY month left on `expiresAt` and takes no cap —
125	    // see the note on it. Charging the full stacked duration here is what makes the
126	    // mirror-image downgrade credit safe to pay out over the same duration: after
127	    // this charge the customer has genuinely paid the new plan's rate for every one
128	    // of those months. Capping this side alone would mint money on a round trip;
129	    // capping the credit side alone destroyed $362.88 of it until 2026-07-26.
130	    prorateCents = prorateUpgradeCents({
131	      fromMonthlyCents: server.plan.priceCents,
132	      toMonthlyCents: newPlan.priceCents,
133	      termMonths: server.termMonths,
134	      termPromoPercent: server.termPromoPercent,
135	      // So an annual server's upgrade prices its effective monthly at the SAME
136	      // admin discount its order and renewals use (matched by the downgrade credit).
137	      annualDiscountPct: await annualDiscountPct(),
138	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
139	    });
140	  }
141	  return { server, newPlan, prorateCents };
142	}
143	
144	/**
145	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
146	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
147	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
148	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
149	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
150	 *
151	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
152	 * amount the customer paid into their wallet at checkout so the debit here nets to
153	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
154	 * spend the just-credited funds). The wallet path omits it and debits the quote.
155	 */
156	export async function applyResize(opts: {
157	  serverId: string;
158	  planId: string;
159	  actorUserId: string;
160	  chargeCents?: number;
161	}): Promise<void> {
162	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
163	  const prorateCents = opts.chargeCents ?? quoted;
164	
165	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
166	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
167	
168	  try {
169	    await db.$transaction(async (tx) => {
170	      if (prorateCents > 0) {
171	        await debitWallet(tx, server.userId, prorateCents);
172	        await tx.walletTransaction.create({
173	          data: {
174	            userId: server.userId,
175	            amountCents: -prorateCents,
176	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
177	          },
178	        });
179	        // PAID invoice for the proration charge (one per user-initiated resize).
180	        await tx.invoice.create({
181	          data: invoiceCreateData({
182	            userId: server.userId,
183	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
184	            status: "PAID",
185	            lineItems: [
186	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
187	            ],
188	          }),
189	        });
190	      }
191	      // NOTE: a plan change deliberately does NOT touch `termPromoPercent`. It does
192	      // not re-base the term — `expiresAt` is untouched and no new months are sold —
193	      // it only moves the customer to a different plan at the rate they already
194	      // bought. Keeping the scalar is exactly what makes upgrade-then-downgrade net
195	      // to zero: both halves read the same stored basis. (This is also why the basis
196	      // is stored as a percent rather than a $/mo figure: a cents rate would have to
197	      // be rewritten here, and that rewrite is one more place to get it wrong.)
198	      //
199	      // Record the amount charged on the job so the worker's RESIZE handler can
200	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
201	      // resize terminally fails — money is committed here, before the job runs.
202	      await tx.job.create({
203	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
204	      });
