1	/**
2	 * Mid-term BACKUP TIER upgrade — the money path for raising ONE server's backup
3	 * RETENTION tier (FREE keep 2 -> PLUS keep 7) without touching its plan.
4	 *
5	 * Deliberately mirrors lib/disk-expand.ts line-for-line so the two paid-upgrade
6	 * money paths cannot drift apart:
7	 *   - `backupUpgradeQuote` is the ONLY place the prorated amount is computed, and
8	 *     both the display (server page card) and the charge (applyBackupUpgrade) call
9	 *     it, so the figure shown === the figure debited.
10	 *   - `applyBackupUpgrade` debits the wallet and applies the tier inside ONE
11	 *     $transaction: a rolled-back debit leaves the tier unchanged, and a tier that
12	 *     was applied was always paid for. It re-checks the current tier INSIDE the tx
13	 *     before debiting, so a double-submit can never double-charge.
14	 *
15	 * Two deliberate differences from disk-expand:
16	 *   1. WALLET-ONLY in the MVP (no Stripe mid-term checkout route — deferred to the
17	 *      full build). A customer with no balance can still buy Plus on card at ORDER
18	 *      time through lib/order.ts.
19	 *   2. NO worker job. Unlike growing a disk, retention is just a column the next
20	 *      scheduled prune reads (worker/index.ts backupCreate), so the tier is applied
21	 *      inline and takes effect on the next backup — nothing to reconcile.
22	 *
23	 * UPGRADE-ONLY: there is no downgrade path (baseline FREE is never taken away and no
24	 * refund logic exists here). Game servers are REJECTED — renewalCharge prices a game
25	 * plan as flat all-in with NO add-on lines, so granting one a paid tier would sell a
26	 * tier the renewal engine never bills (the "never grant a paid tier without payment"
27	 * invariant, in reverse).
28	 */
29	import { db } from "./db";
30	import { debitWallet, InsufficientBalanceError } from "./wallet";
31	import { invoiceCreateData } from "./invoices";
32	import { getSettingInt } from "./settings";
33	import { remainingMonths } from "./proration";
34	import {
35	  type BackupTier,
36	  BACKUP_PLUS_DEFAULT_PRICE_CENTS,
37	  backupTierMonthlyCents,
38	  backupTierSpec,
39	} from "./backup-tiers";
40	
41	export class BackupUpgradeError extends Error {}
42	
43	/**
44	 * The Plus monthly price actually charged, from the admin setting
45	 * (`backup_plus_price_cents`, default 299 = $2.99/mo). Single source of truth for
46	 * the order-time upsell, this mid-term upgrade and every renewal, so they cannot
47	 * disagree.
48	 */
49	export async function backupPlusMonthlyCents(): Promise<number> {
50	  const v = await getSettingInt("backup_plus_price_cents", BACKUP_PLUS_DEFAULT_PRICE_CENTS);
51	  return Math.max(0, Math.round(v));
52	}
53	
54	function loadServer(serverId: string) {
55	  return db.server.findUnique({ where: { id: serverId } });
56	}
57	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
58	
59	export type BackupUpgradeQuote = {
60	  server: QuotedServer;
61	  targetTier: BackupTier;
62	  /** Resolved retention the tier grants. */
63	  keep: number;
64	  /** Recurring monthly cost of the tier (billed every renewal). */
65	  monthlyCents: number;
66	  /** One-off charge for the remainder of the CURRENT paid term (0 for free/admin). */
67	  prorateCents: number;
68	};
69	
70	/**
71	 * Validate an upgrade and compute the prorated charge over the ACTUAL remaining
72	 * term — identical maths to diskExpandQuote (monthly cost x every remaining month;
73	 * null expiresAt on free/admin servers => 0). Throws BackupUpgradeError on any guard
74	 * failure. Does NOT check ownership — callers must.
75	 */
76	export async function backupUpgradeQuote(
77	  serverId: string,
78	  targetTier: BackupTier,
79	): Promise<BackupUpgradeQuote> {
80	  const server = await loadServer(serverId);
81	  if (!server) throw new BackupUpgradeError("Not found");
82	  if (server.gamePlanId) {
83	    throw new BackupUpgradeError("Backup tiers aren't available for game servers yet.");
84	  }
85	  if (targetTier !== "PLUS") throw new BackupUpgradeError("That backup tier isn't available.");
86	  if (server.backupTier === targetTier) {
87	    throw new BackupUpgradeError("This server is already on that backup tier.");
88	  }
89	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
90	    throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
91	  }
92	
93	  const spec = backupTierSpec(targetTier);
94	  const monthlyCents = backupTierMonthlyCents(targetTier, await backupPlusMonthlyCents());
95	  // Remaining-term maths from the SHARED lib/proration.ts helper (same as
96	  // extraDiskProrateCents) so the card's figure and this debit are one derivation.
97	  let prorateCents = 0;
98	  if (!server.isFree && server.expiresAt) {
99	    prorateCents = Math.max(0, Math.round(monthlyCents * remainingMonths(server.expiresAt, Date.now())));
100	  }
101	  return { server, targetTier, keep: spec.keep, monthlyCents, prorateCents };
102	}
103	
104	/**
105	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
106	 * the wallet transaction + PAID invoice, and stamp the tier + resolved retention on
107	 * the server — all in ONE $transaction. `chargeCents` overrides the recomputed
108	 * proration for a caller that already collected an exact amount (parity with
109	 * applyDiskExpand, unused in the wallet-only MVP). Throws BackupUpgradeError on any
110	 * guard failure or insufficient balance.
111	 */
112	export async function applyBackupUpgrade(opts: {
113	  serverId: string;
114	  targetTier: BackupTier;
115	  actorUserId: string;
116	  chargeCents?: number;
117	}): Promise<void> {
118	  const quote = await backupUpgradeQuote(opts.serverId, opts.targetTier);
119	  const { server, targetTier, keep, monthlyCents } = quote;
120	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
121	  const spec = backupTierSpec(targetTier);
122	  const label = `${spec.label} backups (keep ${keep})`;
123	
124	  try {
125	    await db.$transaction(async (tx) => {
126	      // Re-read the tier INSIDE the tx before any money moves: two concurrent
127	      // upgrades (a double-click) both quote FREE, but only the first commits PLUS;
128	      // the second sees PLUS here and aborts before debiting — no double charge.
129	      const fresh = await tx.server.findUnique({
130	        where: { id: server.id },
131	        select: { backupTier: true, status: true },
132	      });
133	      if (!fresh) throw new BackupUpgradeError("Not found");
134	      if (fresh.backupTier === targetTier) {
135	        throw new BackupUpgradeError("This server is already on that backup tier.");
136	      }
137	      if (!["RUNNING", "STOPPED"].includes(fresh.status)) {
138	        throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
139	      }
140	
141	      if (prorateCents > 0) {
142	        await debitWallet(tx, server.userId, prorateCents);
143	        await tx.walletTransaction.create({
144	          data: {
145	            userId: server.userId,
146	            amountCents: -prorateCents,
147	            description: `${label} (prorated) — ${server.hostname}`,
148	          },
149	        });
150	        await tx.invoice.create({
151	          data: invoiceCreateData({
152	            userId: server.userId,
153	            description: `${label} (prorated) — ${server.hostname}`,
154	            status: "PAID",
155	            lineItems: [
156	              {
157	                description:
158	                  `${label} — prorated for remaining term (${server.hostname}). ` +
159	                  `Renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
160	                qty: 1,
161	                unitCents: prorateCents,
162	                amountCents: prorateCents,
163	              },
164	            ],
165	          }),
166	        });
167	      }
168	      // Apply the tier + resolved retention, and make sure backups actually RUN —
169	      // retention is meaningless without a schedule, so bridge to the columns the
170	      // scheduler (worker/backup-schedule.ts) reads, exactly as the order path does.
171	      await tx.server.update({
172	        where: { id: server.id },
173	        data: {
174	          backupTier: targetTier,
175	          backupKeep: keep,
176	          autoBackup: true,
177	          backupIntervalHours: spec.intervalHours,
178	        },
179	      });
180	      await tx.auditLog.create({
181	        data: {
182	          userId: opts.actorUserId,
183	          action: "server.backup_upgrade",
184	          detail: `${server.id} -> ${targetTier} keep=${keep} prorate=${prorateCents}`,
185	        },
186	      });
187	    });
188	  } catch (e) {
189	    if (e instanceof InsufficientBalanceError) {
190	      throw new BackupUpgradeError("Insufficient balance — top up your wallet first.");
191	    }
192	    throw e;
193	  }
194	}
