60	/** A free jailed username on the node, derived from the email + random salt. */
61	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
62	  for (let i = 0; i < 8; i++) {
63	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
64	    if (!isValidUnixUsername(name)) continue;
65	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
66	    if (!taken) return name;
67	  }
68	  throw new Error("Could not allocate a username — try again.");
69	}
