71	/**
72	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
73	 * as every other paid path: no spending while impersonating, verified email,
74	 * wallet charge in the same tx that creates the record. The account starts
75	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
76	 * enabled — see worker/hosting.ts).
77	 */
78	export async function orderHostingAccount(planId: string, domain: string): Promise<HostingResult> {
79	  const user = await requireUser();
80	  await assertNotImpersonating();
81	  const unverified = await emailVerificationError(user);
82	  if (unverified) return { error: unverified };
83	
84	  const name = normalizeHostingDomain(domain);
85	  if (!name) return { error: "Enter a domain." };
86	  if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
87	
88	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
89	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
90	
91	  // One account per domain across ALL customers — same cross-tenant guard as
92	  // email subscriptions (a shared vhost keys on server_name).
93	  const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
94	  if (dupe) {
95	    return {
96	      error:
97	        dupe.userId === user.id
98	          ? "You already have a hosting account for this domain."
99	          : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
100	    };
101	  }
102	  // Also reject if this hostname is already someone's subdomain or addon domain
103	  // (audit HIGH-2: the primary-order guard used to ignore those two tables).
104	  if (await isHostnameClaimed(name)) {
105	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
106	  }
107	
108	  const node = await scheduleHostingNode();
109	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
110	
111	  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
112	  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
113	  // claim inside the charge tx succeeds — otherwise (already redeemed by this
114	  // account/IP, or the promo is off) the account is created at FULL price. We
115	  // pre-check eligibility only to pick the balance gate: a first-time customer with
116	  // a $0 balance can still sign up free, a repeat one is gated against full price.
117	  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
118	  // product the promo applies to. See firstMonthFreeAppliesTo.
119	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
120	  const campaign = promoCampaignFromCookie(await cookies());
121	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
122	  const fullCharge = plan.priceCents;
123	  const promoCharge = 0;
124	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
125	  const anticipated = eligible ? promoCharge : fullCharge;
126	  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
127	
128	  const limits = planLimits(plan);
129	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
130	
131	  let accountId = "";
132	  try {
133	    await db.$transaction(async (tx) => {
134	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
135	      let debitCents = fullCharge;
136	      let promoClaimId: string | null = null;
137	      if (promoEnabled) {
138	        const claim = await claimFirstMonthFree(tx, {
139	          userId: user.id,
140	          ipHash,
141	          serviceType: "HOSTING",
142	          campaign,
143	          chargedCents: promoCharge,
144	        });
145	        if (claim.claimed) {
146	          debitCents = promoCharge;
147	          promoClaimId = claim.id;
148	        }
149	      }
150	      const note = debitCents < fullCharge ? " — First month free" : "";
151	      await debitWallet(tx, user.id, debitCents);
152	      await tx.walletTransaction.create({
153	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name}${note}` },
154	      });
155	      const acct = await tx.hostingAccount.create({
156	        data: {
157	          userId: user.id,
158	          hostingNodeId: node.id,
159	          planId: plan.id,
160	          username,
161	          primaryDomain: name,
162	          status: "PENDING",
163	          diskQuotaMB: limits.diskGB * 1024,
164	          maxSites: limits.maxSites,
165	          maxDatabases: limits.maxDatabases,
166	          expiresAt: addMonths(new Date(), 1),
167	        },
168	      });
169	      accountId = acct.id;
170	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
171	    });
172	  } catch (e) {
173	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
174	  }
175	
176	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
177	  revalidatePath("/dashboard/hosting");
178	  return { ok: true, accountId };
179	}
