386	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
387	  const user = await requireUser();
388	  // A DONE task result can carry a one-time secret (the WordPress admin password);
389	  // an impersonating admin must not read it out (audit LOW-1, same as reveal above).
390	  await assertNotImpersonating();
391	  const a = await db.hostingAccount.findUnique({ where: { id: accountId }, select: { userId: true } });
392	  if (!a) return [];
393	  if (a.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
394	  const rows = await db.hostingTask.findMany({ where: { accountId }, orderBy: { createdAt: "desc" }, take: 8 });
395	  // A DONE result may carry a one-time secret (WordPress admin pw). Return it once,
396	  // then clear it so it isn't shown again on the next poll.
397	  const out = rows.map((t) => ({ id: t.id, kind: t.kind, status: t.status, result: t.result, error: t.error, createdAt: t.createdAt.toISOString() }));
398	  const toClear = rows.filter((t) => t.status === "DONE" && t.result);
399	  if (toClear.length) await db.hostingTask.updateMany({ where: { id: { in: toClear.map((t) => t.id) } }, data: { result: null } });
400	  return out;
401	}
