144	    revalidatePath("/dashboard/billing");
145	  }
146	  return result;
147	}
148	
149	/**
150	 * Redeem a multi-use CREDIT_CENTS coupon (e.g. a "free month" promo) straight
151	 * into the wallet — no top-up/purchase required. Enforces enabled / active /
152	 * expiry / per-coupon `maxRedemptions` / one-per-user / first-time-only, all
153	 * race-safe: the limit is an atomic conditional increment, and the per-user cap
154	 * is the `@@unique([couponId,userId])` on CouponRedemption (a concurrent
155	 * double-redeem throws and rolls the whole transaction back).
156	 */
157	async function redeemCreditCoupon(
158	  user: User,
159	  code: string
160	): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
161	  if (!(await getSettingBool("coupons_enabled", true))) {
162	    return { error: "Promo codes are currently disabled." };
163	  }
164	  const coupon = await db.coupon.findUnique({ where: { code } });
165	  if (!coupon || !coupon.active) {
166	    return { error: "That code isn't valid. Check for typos and try again." };
167	  }
168	  if (coupon.kind !== "CREDIT_CENTS") {
169	    // PERCENT / FIXED_CENTS are discounts on a top-up, entered when adding funds.
170	    return { error: "This code is a discount on a top-up — enter it when you add funds." };
171	  }
172	  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
173	    return { error: "This code has expired." };
174	  }
175	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
176	    return { error: "This code has reached its redemption limit." };
177	  }
178	  const already = await db.couponRedemption.findUnique({
179	    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
180	  });
181	  if (already) return { error: "You've already used this code." };
182	  if (coupon.firstTimeOnly) {
183	    const priorCredits = await db.walletTransaction.count({
184	      where: { userId: user.id, amountCents: { gt: 0 } },
185	    });
186	    if (priorCredits > 0) return { error: "This code is for first-time customers only." };
187	  }
188	
189	  const result = await db
190	    .$transaction(async (tx) => {
191	      // Atomic limit claim — only proceeds while under the cap (skipped if uncapped).
192	      if (coupon.maxRedemptions !== null) {
193	        const claim = await tx.coupon.updateMany({
194	          where: { id: coupon.id, timesRedeemed: { lt: coupon.maxRedemptions } },
195	          data: { timesRedeemed: { increment: 1 } },
196	        });
197	        if (claim.count !== 1) return { error: "This code has reached its redemption limit." };
198	      } else {
199	        await tx.coupon.update({ where: { id: coupon.id }, data: { timesRedeemed: { increment: 1 } } });
200	      }
201	      // One-per-user via the unique constraint (a race throws → full rollback).
202	      await tx.couponRedemption.create({
203	        data: { couponId: coupon.id, userId: user.id, amountCents: coupon.value, context: "free-credit" },
204	      });
205	      await tx.user.update({
206	        where: { id: user.id },
207	        data: { balanceCents: { increment: coupon.value } },
208	      });
209	      await tx.walletTransaction.create({
210	        data: { userId: user.id, amountCents: coupon.value, description: `Promo code redeemed (${coupon.code})` },
211	      });
212	      return { ok: true, amountCents: coupon.value };
213	    })
214	    .catch(() => ({ error: "You've already used this code." }) as { error: string });
215	
216	  if ("ok" in result && result.ok) revalidatePath("/dashboard/billing");
217	  return result;
218	}
219

  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
    return { ok: false, kind: "unavailable", message };
  }
  return { ok: false, kind: "transient", message };
}

/** Drop a stale payment method so the UI stops claiming a card is on file. */
export async function forgetMissingPaymentMethod(userId: string): Promise<void> {
  await clearCardColumns(userId);
  await db.auditLog.create({
    data: {
      userId,
      action: "card.missing_at_stripe",
      detail: "Saved payment method no longer exists at Stripe — cleared locally",
    },
  });
}

/**
 * Credit the wallet for money a card just paid, exactly once.
 *
 * Idempotency is the UNIQUE index on `WalletTransaction.stripePaymentIntentId`,
 * NOT a read-then-write check: a retried sweep and a replayed Stripe request can
 * both arrive with the same intent id, and only the database can safely pick the
 * winner. P2002 means someone already credited it — that is a success, not an error.
 *
 * No invoice for a renewal leg: the renewal transaction issues one PAID invoice
 * for the whole renewal, and a second document for the card portion would
 * double-count the same revenue. Callers that ARE the whole payment (a wallet
 * auto-top-up) pass `invoiceDescription` and get one in the same guarded write.
 */
export async function creditOffSessionCharge(opts: {
  userId: string;
  amountCents: number;
  description: string;
  paymentIntentId: string;
  invoiceDescription?: string;
}): Promise<boolean> {
  if (opts.amountCents <= 0) return false;
  try {
    await db.$transaction([
      db.walletTransaction.create({
        data: {
          userId: opts.userId,
          amountCents: opts.amountCents,
          description: opts.description,
          stripePaymentIntentId: opts.paymentIntentId,
        },
      }),
      db.user.update({
        where: { id: opts.userId },
        data: { balanceCents: { increment: opts.amountCents } },
      }),
      ...(opts.invoiceDescription
        ? [
            db.invoice.create({
              data: invoiceCreateData({
                userId: opts.userId,
                description: opts.invoiceDescription,
                status: "PAID",
                lineItems: [
                  {
                    description: opts.invoiceDescription,
                    qty: 1,
                    unitCents: opts.amountCents,
                    amountCents: opts.amountCents,
                  },
                ],
              }),
            }),
          ]
        : []),
    ]);
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // already credited
    throw e;
  }
}

/**
 * Hosted Checkout link for an outstanding renewal balance.
 *
 * Carries ONLY `nxeonUserId` in metadata, which makes the shared, already-proven
 * fulfilment path treat it as a wallet top-up: the money lands as wallet credit
 * and the next sweep renews from the wallet. That is why this is also the answer
 * to 3-D Secure — Checkout collects the bank challenge on Stripe's own page, so we
 * never need Stripe.js in the browser or a second confirmation code path.
 *
 * The quoted amount is the remainder the wallet cannot cover AT THIS MOMENT. If
 * the customer spends their credit before paying, the next sweep simply recomputes
 * the split and asks the card for the new remainder — it self-heals rather than
 * over- or under-charging.
 */
export async function createOutstandingCheckout(opts: {
  user: { id: string; email: string; stripeCustomerId: string | null };
  amountCents: number;
  hostname: string;
  serverId: string;
}): Promise<string | null> {
  if (!stripeConfigured()) return null;

  newExpiry: Date;
}): Promise<"renewed" | "insufficient" | "already"> {
  const { server, charge, newExpiry } = opts;
  const renewCents = charge.totalCents;
  const { extraDiskCents, extraDiskMonthlyCents, backupCents, backupMonthlyCents } = charge;
  const periodStart = server.expiresAt!;

  // `renewalCharge` bills `vpsTermPriceCents` (or a game plan's flat price) with NO
  // seasonal promo — renewals never get the intro discount, exactly as
  // lib/promotions.ts promises. So the months this renewal adds were sold at 0% off
  // and the term's stored rate basis must say so, or a later downgrade credits them
  // at a promo rate nobody was ever charged. Blended rather than overwritten for the
  // same reason as renewNow: this sweep only fires on already-expired servers (so
  // the blend is 0 in practice), but the shared helper means the two renewal paths
  // cannot express different rules for the same event.
  const renewedPercent = prorateBlendPercent({
    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
    currentMonths: remainingMonths(server.expiresAt, Date.now()),
    addedPercent: 0,
    addedMonths: charge.months,
  });

  try {
    await db.$transaction(async (tx) => {
      const advanced = await tx.server.updateMany({
        where: { id: server.id, expiresAt: server.expiresAt },
        data: {
          expiresAt: newExpiry,
          termPromoPercent: renewedPercent,
          // The period is paid, so the collection state that belonged to it dies
          // with it. Leaving a stage behind would hand the NEXT period a
          // half-spent retry budget and the wrong dunning email.
          dunningStage: 0,
          dunningNextAt: null,
          dunningPayUrl: null,
        },
      });
      if (advanced.count === 0) throw new AlreadyRenewedError();
      await debitWallet(tx, server.userId, renewCents);
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: -renewCents,
          description: `Renewal: ${charge.label} (${server.hostname})`,
        },
      });
      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
      // never producing a second invoice for the same period.
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Renewal: ${charge.label} (${server.hostname})`,
          status: "PAID",
          // Snapshot the card on file at charge time (null-safe for wallet-only users).
          paidBrand: server.user.cardBrand ?? null,
          paidLast4: server.user.cardLast4 ?? null,
          period: { start: periodStart, end: newExpiry },
          // Extra disk gets its OWN line so the customer sees exactly what the
          // permanent storage costs each cycle; the lines sum back to renewCents.
          lineItems: [
            {
              description: `${charge.label} — ${server.hostname}`,
              qty: 1,
              unitCents: renewCents - extraDiskCents - backupCents,
              amountCents: renewCents - extraDiskCents - backupCents,
            },
            ...(extraDiskCents > 0
              ? [
                  {
                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: extraDiskCents,
                    amountCents: extraDiskCents,
                  },
                ]
              : []),
            // Paid backup retention (Plus) gets its own line, mirroring extra disk,
            // so the customer sees exactly what the retention upsell costs each cycle.
            ...(backupCents > 0
              ? [
                  {
                    description: `Plus backups (keep 7) — ${server.hostname} ($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: backupCents,
                    amountCents: backupCents,
                  },
                ]
              : []),
          ],
        }),
      });
      await tx.auditLog.create({
        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
      });
      // First-month-free conversion: this is the server's SECOND term. Flip the
      // redemption anchored to it to renewed (idempotent, same tx as the money).
      await markPromoRenewed(tx, server.id);
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
      return "insufficient";
    }
    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
    throw e;
  }

  // The period is settled. Any 3-D Secure challenge still hanging off it is a
  // loaded gun: anything that later confirms that intent takes a SECOND payment
  // for a period we have already been paid for. Only worth a Stripe round-trip
  // when this server was actually mid-dunning.
  if (server.dunningStage > 0 || server.dunningPayUrl) {
    await cancelPendingChargeForMarker(
      server.user.stripeCustomerId,
      renewalChargeMarker(server.id, periodStart),
    );
  }
  return "renewed";
}

